<?php declare(strict_types=1);header('Content-Type: application/json; charset=utf-8');require_once __DIR__.'/../session-security.php';session_start();sessionSecurityEnforce();require_once __DIR__.'/../mapa/banco.php';require_once __DIR__.'/../auth.php';$pdo=db();authInit($pdo);authRequirePermission($pdo,'professor.chamadas');$pid=authProfessorId();function o($x,$s=200){http_response_code($s);echo json_encode($x,JSON_UNESCAPED_UNICODE);exit;}if(!$pid)o(['ok'=>false,'error'=>'Professor não vinculado ao login.'],403);$a=$_GET['action']??'';
if($a==='turmas'){$s=$pdo->prepare("SELECT ag.id agenda_id,t.id turma_id,t.nome turma,ag.dia,ag.horario,s.nome sala,(SELECT COUNT(*) FROM matriculas m WHERE m.agenda_id=ag.id AND m.status='ativo' AND COALESCE(m.status_participacao,'ativo') NOT IN ('concluido','reprovado')) alunos FROM agenda ag JOIN turmas t ON t.id=ag.turma_id LEFT JOIN salas s ON s.id=ag.sala_id WHERE t.prof_id=? ORDER BY CASE ag.dia WHEN 'Segunda' THEN 1 WHEN 'Terça' THEN 2 WHEN 'Quarta' THEN 3 WHEN 'Quinta' THEN 4 WHEN 'Sexta' THEN 5 WHEN 'Sábado' THEN 6 ELSE 7 END,ag.horario,t.nome");$s->execute([$pid]);$r=[];foreach($s as$x)$r[]=['agendaId'=>(int)$x['agenda_id'],'turmaId'=>(int)$x['turma_id'],'turma'=>$x['turma'],'dia'=>$x['dia'],'horario'=>$x['horario'],'sala'=>$x['sala'],'alunos'=>(int)$x['alunos']];o(['ok'=>true,'turmas'=>$r]);}
if($a==='chamada'){$aid=(int)($_GET['agendaId']??0);$data=(string)($_GET['data']??date('Y-m-d'));$s=$pdo->prepare("SELECT ag.id,t.id turma_id,t.nome turma,ag.dia,ag.horario,s.nome sala FROM agenda ag JOIN turmas t ON t.id=ag.turma_id LEFT JOIN salas s ON s.id=ag.sala_id WHERE ag.id=? AND t.prof_id=?");$s->execute([$aid,$pid]);$ag=$s->fetch();if(!$ag)o(['ok'=>false,'error'=>'Esta turma não pertence ao seu login.'],403);$c=$pdo->prepare("SELECT id FROM chamadas WHERE agenda_id=? AND data_aula=? LIMIT 1");$c->execute([$aid,$data]);$cid=(int)($c->fetchColumn()?:0);$q=$pdo->prepare("SELECT a.id,a.nome,COALESCE(m.status_participacao,'ativo') status,".($cid?"COALESCE((SELECT presente FROM presencas p WHERE p.chamada_id=$cid AND p.aluno_id=a.id),1)":"1")." presente FROM matriculas m JOIN alunos a ON a.id=m.aluno_id WHERE m.agenda_id=? AND m.status='ativo' AND COALESCE(m.status_participacao,'ativo') NOT IN ('concluido','reprovado') ORDER BY a.nome");$q->execute([$aid]);$al=[];foreach($q as$x)$al[]=['id'=>(int)$x['id'],'nome'=>$x['nome'],'status'=>$x['status'],'presente'=>(int)$x['presente']];o(['ok'=>true,'agendaId'=>$aid,'turmaId'=>(int)$ag['turma_id'],'turma'=>$ag['turma'],'dia'=>$ag['dia'],'horario'=>$ag['horario'],'sala'=>$ag['sala'],'data'=>$data,'alunos'=>$al]);}
if($a==='salvar_chamada'){$d=json_decode(file_get_contents('php://input'),true)?:[];$aid=(int)($d['agendaId']??0);$data=(string)($d['data']??'');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$data))o(['ok'=>false,'error'=>'Data inválida.'],422);$s=$pdo->prepare("SELECT ag.id,t.id turma_id,ag.dia,ag.horario FROM agenda ag JOIN turmas t ON t.id=ag.turma_id WHERE ag.id=? AND t.prof_id=?");$s->execute([$aid,$pid]);$ag=$s->fetch();if(!$ag)o(['ok'=>false,'error'=>'Esta turma não pertence ao seu login.'],403);$pdo->beginTransaction();try{$ins=$pdo->prepare("INSERT INTO chamadas(turma_id,agenda_id,dia,horario,data_aula,professor_id,registrado_em) VALUES(?,?,?,?,?,?,CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE professor_id=VALUES(professor_id),agenda_id=VALUES(agenda_id),registrado_em=CURRENT_TIMESTAMP");$ins->execute([(int)$ag['turma_id'],$aid,$ag['dia'],$ag['horario'],$data,$pid]);$c=$pdo->prepare("SELECT id FROM chamadas WHERE turma_id=? AND data_aula=? AND horario=?");$c->execute([(int)$ag['turma_id'],$data,$ag['horario']]);$cid=(int)$c->fetchColumn();$valid=$pdo->prepare("SELECT 1 FROM matriculas WHERE aluno_id=? AND agenda_id=? AND status='ativo'");$up=$pdo->prepare("INSERT INTO presencas(chamada_id,aluno_id,presente)VALUES(?,?,?) ON DUPLICATE KEY UPDATE presente=VALUES(presente)");foreach(($d['presencas']??[])as$p){$al=(int)($p['alunoId']??0);$valid->execute([$al,$aid]);if($valid->fetchColumn())$up->execute([$cid,$al,!empty($p['presente'])?1:0]);}$pdo->commit();o(['ok'=>true,'chamadaId'=>$cid]);}catch(Throwable$e){$pdo->rollBack();o(['ok'=>false,'error'=>'Não foi possível salvar a chamada.'],500);}}
o(['ok'=>false,'error'=>'Ação inválida.'],404);
